"""Pin motion/RETF8 multiply/scanner instructions, SS effects and caller context."""
import argparse, hashlib, json, struct, sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT/'analysis/tools/python'))
from capstone import Cs,CS_ARCH_X86,CS_MODE_16
def main():
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('--output',type=Path,required=True);a=p.parse_args();out=a.output.resolve();assert out.is_relative_to(ROOT/'docs/recovery/evidence') and not out.exists()
 d=(ROOT/'analysis/derived/td2ega-v1/TD2EGA.image.bin').read_bytes();sha=hashlib.sha256(d).hexdigest();assert sha=='8db38a02cc318a62b15928e217bb9f935699c6566088c21d32382a1c908a59c4';gp='analysis/flow/indirect-v8/direct-flow.json';g=json.loads((ROOT/gp).read_text());m=Cs(CS_ARCH_X86,CS_MODE_16)
 entries=['06B3:0008','13A8:2EE8','06C9:44A6'];fs=[f for f in g['functions'] if f['entry'] in entries]
 def view(seg,ip):
  i=next(m.disasm(d[seg*16+ip:seg*16+ip+15],ip,count=1));return {'site':f'{seg:04X}:{ip:04X}','bytes':i.bytes.hex(),'text':i.mnemonic+' '+i.op_str}
 observations=[view(int(f['entry'][:4],16),ip) for f in fs for ip in f['instructions']];assert len(observations)==166
 expected={(0x6b3,8):'55',(0x6b3,9):'8bec',(0x6b3,0xb):'83ec04',(0x6b3,0x2a):'8946fe',(0x6b3,0x30):'98',(0x6b3,0x36):'8946fc',(0x6b3,0x111):'99',(0x6b3,0x114):'9ae82ea813',(0x6b3,0x15d):'8be5',(0x6b3,0x15f):'5d',(0x6b3,0x160):'cb',(0x13a8,0x2ee8):'55',(0x13a8,0x2eeb):'8b4608',(0x13a8,0x2eee):'8b5e0c',(0x13a8,0x2ef3):'8b5e0a',(0x13a8,0x2ef8):'8b4606',(0x13a8,0x2f00):'ca0800',(0x13a8,0x2f19):'ca0800',(0x6c9,0x44aa):'b90500',(0x6c9,0x44ad):'bfda33',(0x6c9,0x44b0):'fd',(0x6c9,0x44b1):'f2ae',(0x6c9,0x44b3):'fc',(0x6c9,0x44b6):'d1e1',(0x6c9,0x44ba):'ffa7dc33'}
 for (seg,ip),raw in expected.items():assert view(seg,ip)['bytes']==raw,(seg,ip,view(seg,ip))
 callers=[{'owner':f['entry'],**c} for f in g['functions'] for c in f['calls'] if c['target'] in entries]
 assert {c['site'] for c in callers if c['target']=='06B3:0008'}=={'06C9:4261'}
 assert {c['site'] for c in callers if c['target']=='06C9:44A6'}=={'06C9:427D'}
 assert {'06B3:0114','13A8:2EBB','13A8:2F94'}.issubset({c['site'] for c in callers if c['target']=='13A8:2EE8'})
 scan_words=[struct.unpack_from('<H',d,0x178f0+0x33dc+2*i)[0] for i in range(5)];assert set(scan_words)=={0x44bf,0x44c5,0x44d2}
 for index in range(5):assert 2*index in range(0,9,2)
 for lo in range(65536):
  assert ((lo>>9)&65535)<=127
  factor=0x100-(lo>>10);assert 193<=factor<=256
 deps=['docs/recovery/evidence/td2ega-signed-motion-validation-v1.json','docs/recovery/evidence/td2ega-control-ops-validation-v1.json','docs/recovery/evidence/td2ega-long-arithmetic-context-v1.json','docs/recovery/evidence/td2ega-indirect-review-v8.json','docs/recovery/evidence/intel-sign-extension-reference-v1.json','docs/recovery/evidence/intel-far-return-stack-reference-v1.json','analysis/reviews/far-return-stack-probe-v1.json','tools/validation/probe_far_return_stack.py']
 assert all((ROOT/v).is_file() for v in deps),[v for v in deps if not (ROOT/v).is_file()]
 record={'schema':1,'result':'pass','image_sha256':sha,'script_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),'flow_ledger':gp,'flow_ledger_sha256':hashlib.sha256((ROOT/gp).read_bytes()).hexdigest(),'instruction_observations':observations,'instruction_sites_in_fence':166,'root_site_counts':{'motion':123,'multiply':23,'scanner':20},'direct_caller_candidates':callers,'caller_windows':[view(seg,ip) for seg,ip in [(0x6c9,0x4261),(0x6c9,0x4266),(0x6c9,0x426b),(0x6c9,0x427c),(0x6c9,0x427d),(0x6c9,0x4280),(0x6c9,0x40d9),(0x6c9,0x40dc),(0x6c9,0x6601),(0x6c9,0x6603),(0x6c9,0x6605)]],'scanner_initialized_near_words':scan_words,'scanner_code_index_footprint':{'ES_read_offsets':[0x33d6,0x33d7,0x33d8,0x33d9,0x33da],'DS_word_offsets':[0x33dc+2*i for i in range(5)],'current_CS_near_targets':[0x44bf,0x44c5,0x44d2],'additional_known_RET_tail':0x44be,'unknown_target_policy':'Native4before44BAJMP; initialized table identity does not close actual all-writer/domain/lifetime proof.','existing_containing_view':'RS-DOS-000271, conditional on principalDS/ES binding; no new resource extent'},'stack_interfaces':{'motion':'PUSHBP/MOVBP-SP/SUBSP4; SS:[BP-2] error and [BP-4] correction, actual ordered aliases, plainRETF. EntrySP20..FFE0 ensures deepest multiply savedBP atentrySP-20.','multiply':'PUSHBP; operandsSS BP+6/8/10/12. Actualfarframe4bytes andRETF8 consumes12bytes atcallee entry. Only savedBP is written; stableRAM permits frozen scalar multiply with flag reconstruction.','scanner':'No own frame/args; actual nearRET consumes2bytes; SP0..FFFE. AX0 preservesincomingDF/CX/DI/BX; nonzeroSTD/SCASB/CLD clearsDF whether matched or not.'},'facts':['Motionreads andwritescurrentDS fields in instruction order; localSSwrites andargument-CALL pushes can change laterDS reads. No disjoint-local/global assumption in newview.','Word98/99 are CBW/CWD despite Capstone wide mnemonic; signed byteIMUL120/wrapped absolute8000/ordered clamps retained, no numericunits assigned.','Motionfactor is193..256 from0x100-(word30E6>>10), highwordzero; first correction highword fromCWD. Logical32-bit product extraction by byte moves andSUBDH0, not host arithmetic-right-shift.','Standalone multiply fastpath whenbothhighwordszero preservesCX; generalpath returns wrapped cross-termCX and defined finalADD-DX carry/ZF. FastMUL ZF is undefined and omitted frominterface validity.','Scanner comparesALagainstES bytes in reverse order, five code positions; tablewords read viaDS. DSneednot equalES inadditionalbusview; actualcallerESbinding andalltablewriters remainopen.','After4261,6601 invokes synthetic/actualINT16 profile before branching on returnedZF, so no unconditional arithmetic-flag-kill claim for that boundary. After427D,420A returns directly; outer403B40DCCMP33D4 replacesCFZF. Returned DF follows scannerAX0shortcut/nonzeroCLD and earlier service/motion paths.','For420Afar4261, calleeSP=callerSP-4; motioncomponent requirescallerSPatleast24. Scanner nearcalleeSP=callerSP-2. No complete420A-403B stack/IRQ/profile admission from component relations.','Physical086Cunassigned; CGAbehindEGAclosure; no DOSsession/realdevices/IRQ/renderer/audio/fullresources/complete-state-machine/gameplay/fidelity.'],'validator_dependencies':[{'path':v,'sha256':hashlib.sha256((ROOT/v).read_bytes()).hexdigest()} for v in deps],'limits':'166sites/threeadditionalactualSSinterfaces/farplainRETF-versusRETF8/orderedDS-SSlocals-and-frames/definedCFZF/ESscannerandrawnearJMP. Existingoriginalentries countedonce; oldsource-DLL-receiptsfrozen. Whole420A-403B/actualcaller-validdomains-allwriters-capacity-lifetime-exclusion-IRQ/core/P1-GATE remainopen.'}
 out.write_text(json.dumps(record,indent=2)+'\n');print(json.dumps({'result':'pass','sites':166,'callers':len(callers),'new_resource_extents':0}))
if __name__=='__main__':main()
